CREATE ROLE ${adminRole} LOGIN PASSWORD '${adminPass}' NOSUPERUSER NOBYPASSRLS;
GRANT USAGE, CREATE ON SCHEMA nexus, t1, public TO ${adminRole};
DO $$
DECLARE r record;
BEGIN
    FOR r IN SELECT schemaname, tablename FROM pg_tables WHERE schemaname IN ('nexus', 't1') LOOP
        EXECUTE format('ALTER TABLE %I.%I OWNER TO ${adminRole}', r.schemaname, r.tablename);
    END LOOP;
    FOR r IN SELECT schemaname, sequencename FROM pg_sequences WHERE schemaname IN ('nexus', 't1') LOOP
        EXECUTE format('ALTER SEQUENCE %I.%I OWNER TO ${adminRole}', r.schemaname, r.sequencename);
    END LOOP;
END
$$;

DROP VIEW IF EXISTS nexus.diag_chash_conformance;
ALTER TABLE nexus.topic_assignments DROP CONSTRAINT IF EXISTS topic_assignments_chunk_fk;
ALTER TABLE nexus.topic_assignments ALTER COLUMN doc_id TYPE TEXT USING encode(doc_id, 'hex');
CREATE VIEW nexus.diag_chash_conformance AS SELECT 1 AS n;
